{
  "name": "@ai-hero/sandcastle",
  "version": "0.14.0",
  "description": "CLI for orchestrating AI agents in isolated sandbox environments",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./sandboxes/docker": {
      "import": "./dist/sandboxes/docker.js",
      "types": "./dist/sandboxes/docker.d.ts"
    },
    "./sandboxes/e2b": {
      "import": "./dist/sandboxes/e2b.js",
      "types": "./dist/sandboxes/e2b.d.ts"
    },
    "./sandboxes/vercel": {
      "import": "./dist/sandboxes/vercel.js",
      "types": "./dist/sandboxes/vercel.d.ts"
    },
    "./sandboxes/podman": {
      "import": "./dist/sandboxes/podman.js",
      "types": "./dist/sandboxes/podman.d.ts"
    },
    "./sandboxes/daytona": {
      "import": "./dist/sandboxes/daytona.js",
      "types": "./dist/sandboxes/daytona.d.ts"
    },
    "./sandboxes/modal": {
      "import": "./dist/sandboxes/modal.js",
      "types": "./dist/sandboxes/modal.d.ts"
    },
    "./sandboxes/no-sandbox": {
      "import": "./dist/sandboxes/no-sandbox.js",
      "types": "./dist/sandboxes/no-sandbox.d.ts"
    },
    "./sandboxes/bwrap": {
      "import": "./dist/sandboxes/bwrap.js",
      "types": "./dist/sandboxes/bwrap.d.ts"
    },
    "./sandboxes/seatbelt": {
      "import": "./dist/sandboxes/seatbelt.js",
      "types": "./dist/sandboxes/seatbelt.d.ts"
    },
    "./sandboxes/sprites": {
      "import": "./dist/sandboxes/sprites.js",
      "types": "./dist/sandboxes/sprites.d.ts"
    }
  },
  "bin": {
    "sandcastle": "dist/main.js"
  },
  "scripts": {
    "build": "tsup",
    "postbuild": "node scripts/copy-templates.mjs && node scripts/check-public-types-effect-free.mjs",
    "pretest": "tsx scripts/ensure-build.ts",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:local": "vitest run --config vitest.local.config.ts",
    "typecheck": "tsc --noEmit && tsc --noEmit -p tests/tsconfig.json",
    "prelint": "tsx scripts/ensure-build.ts",
    "lint": "tsc --noEmit -p scripts/tsconfig.json && tsx scripts/lint-ratchet.ts",
    "lint:shrink": "tsx scripts/lint-ratchet.ts --shrink",
    "prelint:report": "tsx scripts/ensure-build.ts",
    "lint:report": "tsx scripts/lint-ratchet.ts --report",
    "format": "biome format --write .",
    "format:check": "biome format .",
    "prepare": "husky",
    "release": "changeset publish",
    "sandcastle": "npm run build && tsx .sandcastle/run.ts",
    "test-podman": "npm run build && tsx --env-file=.sandcastle/.env .sandcastle/test-podman.ts",
    "test-vercel": "npm run build && tsx --env-file=.sandcastle/.env .sandcastle/test-vercel.ts",
    "test-interactive": "npm run build && tsx --env-file=.sandcastle/.env .sandcastle/test-interactive.ts",
    "verify": "tsx .sandcastle/verify/verify.ts",
    "verify:world": "npm run build >/dev/null && tsx .sandcastle/verify/verify.ts world",
    "coverage:gate": "tsx scripts/coverage-gate.ts",
    "coverage:floor": "tsx scripts/coverage-floor.ts",
    "api:report": "tsx scripts/api-report.ts"
  },
  "keywords": [
    "cli",
    "sandbox",
    "docker",
    "ai",
    "agent"
  ],
  "packageManager": "npm@10.9.2",
  "repository": {
    "type": "git",
    "url": "https://github.com/mattpocock/sandcastle"
  },
  "license": "MIT",
  "devDependencies": {
    "@biomejs/biome": "2.6.4",
    "@changesets/cli": "^2.30.0",
    "@daytona/sdk": "^0.227.0",
    "@effect/cli": "^0.74.0",
    "@effect/language-service": "0.87.5",
    "@effect/platform": "^0.95.0",
    "@effect/platform-node": "^0.105.0",
    "@effect/printer": "^0.48.0",
    "@effect/printer-ansi": "^0.48.0",
    "@fly/sprites": "^0.2.4",
    "@microsoft/api-extractor": "^7.60.1",
    "@types/node": "^25.5.0",
    "@typescript/native": "npm:typescript@7.0.2",
    "@vitest/coverage-v8": "^3.2.4",
    "dependency-cruiser": "^18.7.0",
    "e2b": "^2.62.0",
    "effect": "^3.20.0",
    "husky": "^9.1.7",
    "lint-staged": "^15.5.1",
    "modal": "^0.11.1",
    "oxlint": "1.90.0",
    "oxlint-tsgolint": "7.0.2005",
    "tsup": "^8.5.1",
    "tsx": "^4.21.0",
    "typescript": "npm:@typescript/typescript6@6.0.2",
    "vitest": "^3.2.0",
    "zod": "^4.4.3"
  },
  "dependencies": {
    "@clack/prompts": "^1.1.0"
  },
  "peerDependencies": {
    "@daytona/sdk": ">=0.164.0 <1.0.0",
    "@fly/sprites": ">=0.2.4 <1.0.0",
    "@vercel/sandbox": ">=1.0.0",
    "e2b": ">=2.62.0 <3.0.0",
    "modal": ">=0.11.0 <1.0.0"
  },
  "peerDependenciesMeta": {
    "@vercel/sandbox": {
      "optional": true
    },
    "@daytona/sdk": {
      "optional": true
    },
    "@fly/sprites": {
      "optional": true
    },
    "e2b": {
      "optional": true
    },
    "modal": {
      "optional": true
    }
  },
  "files": [
    "dist"
  ]
}

{
  "name": "dsh-memory-evolve",
  "version": "0.1.0",
  "description": "为 DeepSeek Harness 带来分层记忆（全局 / 用户 / 项目 / GIT 分支 / 每日）与自我进化（经验沉淀 + 技能自动创建）和技能管理、待办管理、CLI 调度（kimi/codex/grok/hermes 等外部 AI 统一调度）、临时信息便签，带 WebUI 管理界面。Hermes-style long-term memory, self-evolution, skills, todos and external CLI agent dispatch for DeepSeek Harness.",
  "private": true,
  "type": "module",
  "main": "lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./client": "./lib/client.js",
    "./package.json": "./package.json"
  },
  "scripts": {
    "test": "node --test 'tests/*.test.js'",
    "build": "node scripts/build.mjs"
  },
  "license": "MIT",
  "dsh": {
    "client": {
      "inject": [
        "@deepseek-ai/dsh-client-runtime"
      ],
      "platform": "web"
    },
    "bundle": {
      "patch": "./cordis.patch.yml"
    }
  }
}
